package org.eda.resolver.domain;

import java.net.URI;
import java.util.UUID;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Component;

/**
 * The only component that builds URIs (AD-03, ADR-0018, ADR-0019).
 *
 * <p>The signature forbids attribute-derived input by construction: the method accepts a
 * tool namespace (configured by registration) and a {@link UUID} (generated by the
 * caller). No overload takes a native id, a path, or any mutable attribute.
 */
@Component
public final class UriGenerator {

    private final String baseDomain;

    public UriGenerator(@Value("${eda.base-domain}") String baseDomain) {
        if (baseDomain == null || baseDomain.isBlank()) {
            throw new IllegalArgumentException("eda.base-domain must be configured");
        }
        this.baseDomain = stripTrailingSlash(baseDomain);
    }

    public URI generate(String toolNamespace, UUID uuid) {
        if (toolNamespace == null || toolNamespace.isBlank()) {
            throw new IllegalArgumentException("toolNamespace is required");
        }
        if (uuid == null) {
            throw new IllegalArgumentException("uuid is required");
        }
        String ns = normalise(toolNamespace);
        return URI.create(baseDomain + ns + uuid);
    }

    public String baseDomain() {
        return baseDomain;
    }

    private static String stripTrailingSlash(String s) {
        return s.endsWith("/") ? s.substring(0, s.length() - 1) : s;
    }

    private static String normalise(String ns) {
        String n = ns.startsWith("/") ? ns : "/" + ns;
        return n.endsWith("/") ? n : n + "/";
    }
}
